package io.xeros.solo;
import io.xeros.*;import io.xeros.content.skills.herblore.*;import io.xeros.content.skills.runecrafting.*;import io.xeros.model.items.GameItem;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.lang.reflect.*;import java.util.*;
public final class HerbloreRunecraftingPlayableCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){return AttackDefencePlayableCheck.actor();}static long xp(Player p,int s){return AttackDefencePlayableCheck.xp(p,s);}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void tick(int n){SkillsAuditCheck.tick(n);}static void clear(Player p){SkillsAuditCheck.clear(p);}static void block(Player p,int m){switch(m){case 0:p.getHealth().setCurrentHealth(0);break;case 1:p.isDead=true;break;case 2:p.isBanking=true;break;case 3:p.isShopping=true;break;case 4:p.teleTimer=3;break;}}
 static void herbs(){
  for(Herb h:Herb.values()){Player p=actor();give(p,h.getGrimy(),2);long old=xp(p,15);p.getHerblore().clean(h.getGrimy());tick(2);ok(count(p,h.getClean())==2&&count(p,h.getGrimy())==0&&xp(p,15)-old==(long)Math.floor(h.getExperience()*10+1e-7)*2,"Herb clean XP "+h);clear(p);}
  for(int m=0;m<5;m++){Player p=actor();give(p,199,1);long old=xp(p,15);block(p,m);p.getHerblore().clean(199);ok(count(p,199)==1&&count(p,249)==0&&xp(p,15)==old,"Immediate clean guard "+m);clear(p);p=actor();give(p,91,1);give(p,221,1);p.getHerblore().mix(91);block(p,m);tick(2);ok(count(p,91)==1&&count(p,221)==1&&count(p,121)==0,"Potion callback "+m);clear(p);}
  int[] id={0,125,123,121,2428};for(int a=1;a<=3;a++)for(int b=1;b<=3;b++){Player p=actor();give(p,id[a],1);give(p,id[b],1);PotionDecanting.get().mix(p,new GameItem(id[a],1,0),new GameItem(id[b],1,1));int total=0;for(int i=1;i<=4;i++)total+=count(p,id[i])*i;ok(total==a+b&&count(p,id[Math.min(4,a+b)])>=1,"Dose conservation "+a+"/"+b);clear(p);}
  Player p=actor();give(p,121,1);give(p,115,1);PotionDecanting.get().mix(p,new GameItem(121,1,0),new GameItem(115,1,1));ok(count(p,121)==1&&count(p,115)==1,"Mixed potion families");PotionDecanting.get().mix(p,new GameItem(121,1,0),new GameItem(121,1,0));ok(count(p,121)==1,"Same slot duplication");clear(p);
  System.out.println("HERBLORE_ALL14_HERBS_EXACT_XP_FIVE_CLEAN_AND_POTION_GUARDS_NINE_DOSE_COMBINATIONS_DIFFERENT_FAMILY_AND_SAME_SLOT_REJECTION_PASS");System.out.println("HERBLORE_PLAYABLE_V62_PASS");
 }
 static void runes()throws Exception{
  int altars=0;for(Runecrafting.RunecraftingData r:Runecrafting.RunecraftingData.values()){if(r.getObjectId()<=0)continue;Player p=actor();give(p,7936,1);long old=xp(p,20);Runecrafting.execute(p,r.getObjectId());ok(count(p,7936)==0&&count(p,r.getRuneId())>0&&xp(p,20)-old==(long)Math.floor(r.getExperience()*10+1e-7),"Altar fractional XP "+r);clear(p);
   p=actor();give(p,7936,2);give(p,r.getRuneId(),Integer.MAX_VALUE-1);old=xp(p,20);Runecrafting.execute(p,r.getObjectId());ok(count(p,7936)==2&&count(p,r.getRuneId())==Integer.MAX_VALUE-1&&xp(p,20)==old,"Altar overflow atomic "+r);clear(p);altars++;
  }
  Method combine=CombinationRune.class.getDeclaredMethod("combine",Player.class,int.class,int.class,java.util.function.DoubleSupplier.class);combine.setAccessible(true);for(CombinationRune r:CombinationRune.values()){Player p=actor();give(p,7936,2);give(p,r.input,2);give(p,r.talisman,1);long old=xp(p,20);combine.invoke(null,p,r.input,r.altar,(java.util.function.DoubleSupplier)()->0);ok(count(p,r.output)==2&&count(p,7936)==0&&count(p,r.input)==0&&count(p,r.talisman)==0&&xp(p,20)-old==(long)Math.floor(r.experience*20+1e-7),"Combination "+r);clear(p);
   p=actor();give(p,7936,2);give(p,r.input,2);give(p,r.talisman,1);give(p,r.output,Integer.MAX_VALUE-1);old=xp(p,20);combine.invoke(null,p,r.input,r.altar,(java.util.function.DoubleSupplier)()->0);ok(count(p,7936)==2&&count(p,r.input)==2&&count(p,r.talisman)==1&&xp(p,20)==old,"Combination overflow "+r);clear(p);
  }
  for(int m=0;m<5;m++){Player p=actor();give(p,7936,1);block(p,m);long old=xp(p,20);Runecrafting.execute(p,25378);ok(count(p,7936)==1&&xp(p,20)==old,"Runecraft guard "+m);clear(p);}
  for(Pouches.Pouch pouch:Pouches.Pouch.values()){Player p=actor();give(p,pouch.pouchId,1);give(p,1436,2);give(p,7936,6);Pouches.fill(p,pouch,pouch.index);int total=p.getRuneEssencePouch(pouch.index)+p.getPureEssencePouch(pouch.index);ok(total==Math.min(8,pouch.capacity),"Pouch capacity "+pouch);Pouches.empty(p,pouch.index);ok(count(p,1436)==2&&count(p,7936)==6&&p.getRuneEssencePouch(pouch.index)+p.getPureEssencePouch(pouch.index)==0,"Pouch exact empty "+pouch);p.getHealth().setCurrentHealth(0);Pouches.fill(p,pouch,pouch.index);ok(count(p,1436)==2&&count(p,7936)==6,"Dead pouch fill");clear(p);}
  System.out.println("RUNECRAFTING_"+altars+"_ALTARS_FRACTIONAL_XP_AND_ATOMIC_OVERFLOW_TWELVE_COMBINATIONS_TALISMANS_FIVE_ACTION_GUARDS_AND_FIVE_POUCH_CAPACITIES_PASS");System.out.println("RUNECRAFTING_PLAYABLE_V62_PASS");
 }
 static void save(){Player p=actor();p.setLoginName("skills62qa");p.setDisplayName("Skills62qa");p.setIndex(1);p.isActive=true;p.saveCharacter=true;PlayerHandler.players[1]=p;p.getPA().addSkillXPMultiplied(2.5,15,true);p.getPA().addSkillXPMultiplied(8.7,20,true);give(p,26784,1);give(p,7936,8);Pouches.fill(p,Pouches.Pouch.COLOSSAL_POUCH,4);long h=xp(p,15),r=xp(p,20);ok(PlayerSave.saveGameInstant(p),"Save");Player q=actor();q.setLoginName("skills62qa");ok(PlayerSave.loadGame(q,"skills62qa","IsolatedAudit",true).toString().equals("SUCCESS")&&xp(q,15)==h&&xp(q,20)==r&&q.getPureEssencePouch(4)==8,"Herblore Runecraft pouch persistence");clear(p);clear(q);PlayerHandler.players[1]=null;System.out.println("HERBLORE_RUNECRAFTING_FRACTIONAL_XP_COLOSSAL_POUCH_REAL_SAVE_RELOAD_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;Field f=io.xeros.content.boosts.Boosts.class.getDeclaredField("boosts");f.setAccessible(true);f.set(null,Collections.emptyList());herbs();runes();save();System.exit(0);}
}

